-- before.sql: READ ONLY on prod, one statement, BEFORE 0431 is pushed (generated by gen.mjs from the migration's own hunks: do not edit by hand).
-- Each of 0431's eleven hunks occurs exactly once in the live body it cuts (want eleven 1s), nothing of 0431 is there yet, the head is 0430,
-- and the sizes the book will read beside (battles, convoy_cargo) and the Stats count's last runs. Catalog reads, pg_get_functiondef (STABLE),
-- the planner's row estimates and stats_runs (7 days of receipts) only.
begin transaction read only;
select jsonb_build_object(
  'head', (select max(version) from supabase_migrations.schema_migrations),
  'absent', to_regclass('public.fleet_book') is null and to_regclass('public.fleet_lines') is null and to_regclass('public.stats_fleet_list') is null
            and to_regprocedure('world.stats_fleet(uuid)') is null and not exists (select 1 from pg_trigger t where t.tgname = 'fleet_book_battle'),
  'hunks', (select jsonb_agg((length(b.def) - length(replace(b.def, h.old, ''))) / length(h.old) order by h.ord)
              from (values
                (1, 'public.navy_fight(uuid,uuid,timestamp with time zone)', $h$  v_ev := public.emit_event(null, 'NAVY_FIGHT', jsonb_build_object(
$h$),
                (2, 'voyage.navy_meets(uuid,integer,uuid,uuid,timestamp with time zone)', $h$  perform public.navy_fine(p_player, h.nation_id, v_fine, p_at);
$h$),
                (3, 'public.navy_pay(timestamp with time zone,uuid)', $h$  select coalesce(array_agg(p.to_port) filter (where p.k <= v_can and p.to_port <> v_cap), '{}') into v_to from p;
$h$),
                (4, 'public.pirate_pay_hour(timestamp with time zone)', $h$    update public.pirate_ships n set unpaid_since = case when v_paid > 0 then null else coalesce(n.unpaid_since, p_now) end where n.fleet_id = r.fleet_id;
$h$),
                (5, 'public.npc_refit_step(uuid,timestamp with time zone)', $h$  perform public.fleet_mend(p_fleet);

  -- A merchant's hands$h$),
                (6, 'public.pirate_reborn(uuid,timestamp with time zone)', $h$  perform public.fleet_mend(p_fleet);
  perform public.fleet_hands(p_fleet, n.home_port);
$h$),
                (7, 'public.pirate_ransom(uuid,uuid,bigint,uuid)', $h$  perform public.pay_city(p_company, n.home_port, 'RANSOM', v_take, p_event);
$h$),
                (8, 'public.pirate_loot_book(uuid,uuid,numeric,uuid)', $h$  perform public.treasury_post(n.home_port, 'LOOT', v_take, null, p_event, true);
$h$),
                (9, 'public.convoy_book(text,uuid,uuid,uuid,bigint,bigint)', $h$  returning id into v_id;
$h$),
                (10, 'public.tick_stats(timestamp with time zone)', $h$  delete from public.stats_fleets x where x.at < p_now - interval '26 hours';
$h$),
                (11, 'public.client_rpc_entry_points()', $h$      ('world',       'stats_fleets',          ''),
$h$)) h(ord, fn, old)
              cross join lateral (select replace(pg_get_functiondef(h.fn::regprocedure), E'\r', '') as def) b),
  'rows_est', (select jsonb_object_agg(c.relname, c.reltuples::bigint) from pg_class c join pg_namespace n on n.oid = c.relnamespace
                where n.nspname = 'public' and c.relname in ('battles', 'battle_sides', 'convoy_cargo', 'navy_ships', 'pirate_ships', 'cargo_ships')),
  'runs', (select jsonb_agg(jsonb_build_object('at', x.at, 'ms', x.ms, 'fleets_ms', x.receipt -> 'phases' -> 'fleets') order by x.at desc)
             from (select r.at, r.ms, r.receipt from public.stats_runs r order by r.at desc limit 4) x)
) as before_0431;
commit;
